import pandas as pd


def load_marks(path):
    return pd.read_csv(path, sep=";", comment="#", na_values=["-"])


def schema(df):
    return {
        "rows": len(df),
        "columns": df.columns.tolist(),
        "missing": int(df["mark"].isna().sum()),
        "mean_mark": round(float(df["mark"].mean()), 2),
    }


df = load_marks("marks.csv")
print(df.head())
print(df.dtypes)
print(schema(df))

